@import "@fontsource/poppins/200.css";
@import "@fontsource/poppins/300.css";
@import "@fontsource/poppins/400.css";
@import "@fontsource/poppins/500.css";
@import "@fontsource/poppins/600.css";

/* Light (faithful): a near-white page, white cards, one warm chocolate-brown ink, taupe
   labels and pill buttons, a pale greige for hovers, a light grey nav pill. */
:root {
  --background: oklch(0.985 0 0);
  --foreground: oklch(0.386 0.017 60);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.386 0.017 60);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.386 0.017 60);
  --primary: oklch(0.595 0.025 54);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.903 0.006 60);
  --secondary-foreground: oklch(0.386 0.017 60);
  --muted: oklch(0.949 0 0);
  --muted-foreground: oklch(0.676 0.019 54);
  --accent: oklch(0.903 0.006 60);
  --accent-foreground: oklch(0.386 0.017 60);
  --destructive: oklch(0.52 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.903 0.006 60);
  --input: oklch(0.619 0.013 59);
  --ring: oklch(0.386 0.017 60);
  --highlight: oklch(0.685 0.106 61);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.825 0.078 68);
  --chart-1: oklch(0.386 0.017 60);
  --chart-2: oklch(0.595 0.025 54);
  --chart-3: oklch(0.685 0.106 61);
  --chart-4: oklch(0.825 0.078 68);
  --chart-5: oklch(0.903 0.006 60);
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0.386 0.017 60);
  --sidebar-primary: oklch(0.595 0.025 54);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.903 0.006 60);
  --sidebar-accent-foreground: oklch(0.386 0.017 60);
  --sidebar-border: oklch(0.903 0.006 60);
  --sidebar-ring: oklch(0.386 0.017 60);

  --typeface-body: "Poppins", "Avenir Next", "Century Gothic", sans-serif;
  --typeface-display: "Poppins", "Avenir Next", "Century Gothic", sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.25rem;
  --page-width: 85rem;
  --page-gutter: 0.9375rem;
  --section-y: 5rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 2.5rem;
    --section-y: 10rem;
  }
}

/* Dark (sibling): an espresso page with deeper brown cards, warm off-white ink, the same
   taupe buttons a touch lighter; the dark bands turn into pale linen bands. */
.dark {
  --background: oklch(0.2 0.008 60);
  --foreground: oklch(0.93 0.008 60);
  --card: oklch(0.25 0.01 60);
  --card-foreground: oklch(0.93 0.008 60);
  --popover: oklch(0.25 0.01 60);
  --popover-foreground: oklch(0.93 0.008 60);
  --primary: oklch(0.62 0.03 54);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.33 0.012 60);
  --secondary-foreground: oklch(0.93 0.008 60);
  --muted: oklch(0.29 0.01 60);
  --muted-foreground: oklch(0.7 0.02 54);
  --accent: oklch(0.33 0.012 60);
  --accent-foreground: oklch(0.93 0.008 60);
  --destructive: oklch(0.65 0.18 25);
  --destructive-foreground: oklch(0.2 0.008 60);
  --border: oklch(0.93 0.008 60 / 14%);
  --input: oklch(0.6 0.013 59);
  --ring: oklch(0.93 0.008 60);
  --highlight: oklch(0.7 0.11 61);
  --highlight-foreground: oklch(0.2 0.008 60);
  --glow: oklch(0.6 0.08 66);
  --chart-1: oklch(0.93 0.008 60);
  --chart-2: oklch(0.62 0.03 54);
  --chart-3: oklch(0.7 0.11 61);
  --chart-4: oklch(0.6 0.08 66);
  --chart-5: oklch(0.33 0.012 60);
  --sidebar: oklch(0.25 0.01 60);
  --sidebar-foreground: oklch(0.93 0.008 60);
  --sidebar-primary: oklch(0.62 0.03 54);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.33 0.012 60);
  --sidebar-accent-foreground: oklch(0.93 0.008 60);
  --sidebar-border: oklch(0.93 0.008 60 / 14%);
  --sidebar-ring: oklch(0.93 0.008 60);
}
